BEGIN;
CREATE TABLE IF NOT EXISTS nexo_ia_config (empresa VARCHAR(20) PRIMARY KEY CHECK (empresa IN ('NOVONET','VELSA')), enabled BOOLEAN NOT NULL DEFAULT FALSE, prompt_negocio TEXT NOT NULL, personalidad TEXT NOT NULL DEFAULT 'Profesional, consultivo, natural y seguro', reglas TEXT NOT NULL DEFAULT '', prohibiciones TEXT NOT NULL DEFAULT '', usar_emojis BOOLEAN NOT NULL DEFAULT FALSE, longitud_maxima INTEGER NOT NULL DEFAULT 900 CHECK (longitud_maxima BETWEEN 100 AND 3000), modelo VARCHAR(120) NOT NULL DEFAULT 'openai/gpt-oss-20b', espera_segundos INTEGER NOT NULL DEFAULT 60 CHECK (espera_segundos BETWEEN 10 AND 3600), limite_minuto INTEGER NOT NULL DEFAULT 10 CHECK (limite_minuto > 0), limite_dia INTEGER NOT NULL DEFAULT 1000 CHECK (limite_dia > 0), version INTEGER NOT NULL DEFAULT 1, actualizado_por VARCHAR(255), actualizado_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS nexo_ia_documentos (id BIGSERIAL PRIMARY KEY, empresa VARCHAR(20) NOT NULL REFERENCES nexo_ia_config(empresa), nombre VARCHAR(255) NOT NULL, mime VARCHAR(120) NOT NULL, checksum CHAR(64) NOT NULL, texto TEXT NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, version INTEGER NOT NULL DEFAULT 1, cargado_por VARCHAR(255), creado_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (empresa, checksum));
CREATE TABLE IF NOT EXISTS nexo_ia_jobs (id BIGSERIAL PRIMARY KEY, empresa VARCHAR(20) NOT NULL, id_bitrix VARCHAR(50) NOT NULL, mensaje_disparador_id VARCHAR(100) NOT NULL, tipo VARCHAR(30) NOT NULL CHECK (tipo IN ('RESPUESTA_AL_CLIENTE','SEGUIMIENTO_COMERCIAL','AUDITORIA_HISTORICA')), prioridad SMALLINT NOT NULL DEFAULT 10, config_version INTEGER NOT NULL, ejecutar_despues TIMESTAMPTZ NOT NULL DEFAULT NOW(), estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE' CHECK (estado IN ('PENDIENTE','GENERANDO','LISTA','FALLIDA','CANCELADA')), intentos SMALLINT NOT NULL DEFAULT 0, bloqueado_por VARCHAR(100), bloqueado_at TIMESTAMPTZ, error_codigo VARCHAR(80), error_detalle TEXT, creado_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), actualizado_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (empresa,id_bitrix,mensaje_disparador_id,tipo,config_version));
ALTER TABLE nexo_ia_jobs ADD COLUMN IF NOT EXISTS instruccion TEXT NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS idx_nexo_jobs_pendientes ON nexo_ia_jobs (prioridad DESC, ejecutar_despues, creado_at) WHERE estado='PENDIENTE';
CREATE TABLE IF NOT EXISTS nexo_ia_sugerencias (id BIGSERIAL PRIMARY KEY, job_id BIGINT UNIQUE REFERENCES nexo_ia_jobs(id), empresa VARCHAR(20) NOT NULL, id_bitrix VARCHAR(50) NOT NULL, tipo VARCHAR(30) NOT NULL, mensaje_disparador_id VARCHAR(100) NOT NULL, diagnostico TEXT, respuesta_sugerida TEXT, tecnica_aplicada TEXT, siguiente_accion TEXT, alertas JSONB NOT NULL DEFAULT '[]'::jsonb, contexto_hash CHAR(64) NOT NULL, contexto_extracto TEXT, modelo VARCHAR(120), prompt_version INTEGER NOT NULL, tokens_entrada INTEGER, tokens_salida INTEGER, latencia_ms INTEGER, creado_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_nexo_sugerencias_lead ON nexo_ia_sugerencias (empresa,id_bitrix,creado_at DESC);
CREATE TABLE IF NOT EXISTS nexo_ia_feedback (id BIGSERIAL PRIMARY KEY, sugerencia_id BIGINT NOT NULL REFERENCES nexo_ia_sugerencias(id), usuario VARCHAR(255) NOT NULL, evento VARCHAR(20) NOT NULL CHECK (evento IN ('UTIL','NO_UTIL','COPIADA','REGENERADA')), comentario TEXT, creado_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS nexo_ia_backfill (empresa VARCHAR(20) PRIMARY KEY, desde DATE NOT NULL DEFAULT DATE '2026-08-15', cursor_fecha TIMESTAMPTZ, cursor_id VARCHAR(50), estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE', procesados INTEGER NOT NULL DEFAULT 0, actualizado_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
COMMIT;
